-- YOSHA STORE core schema. Run in Supabase SQL Editor on a new project.
create extension if not exists pgcrypto;
create type public.app_role as enum ('customer','seller','admin');
create type public.seller_status as enum ('pending','approved','rejected','suspended');
create type public.order_status as enum ('pending','confirmed','processing','shipped','delivered','cancelled');
create type public.payment_status as enum ('unpaid','pending_review','paid','failed','refunded');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade, full_name text, phone text, role public.app_role not null default 'customer', created_at timestamptz not null default now());
create table public.seller_applications(id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, business_name text not null, phone text, description text, status public.seller_status not null default 'pending', reviewed_at timestamptz, created_at timestamptz not null default now());
create table public.stores(id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id), name text not null, slug text not null unique, description text, logo_url text, status public.seller_status not null default 'pending', created_at timestamptz not null default now());
create table public.categories(id uuid primary key default gen_random_uuid(), name text not null, slug text unique not null, parent_id uuid references public.categories(id), active boolean not null default true);
create table public.products(id uuid primary key default gen_random_uuid(), store_id uuid not null references public.stores(id), category_id uuid references public.categories(id), name text not null, slug text not null, description text, price numeric(14,2) not null check(price>=0), currency text not null default 'SDG', stock integer not null default 0 check(stock>=0), image_urls text[] not null default '{}', active boolean not null default false, created_at timestamptz not null default now(), unique(store_id,slug));
create table public.addresses(id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, recipient text not null, phone text not null, city text not null, area text, details text not null, is_default boolean not null default false);
create table public.orders(id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id), order_number text unique not null default ('YS-'||upper(substr(encode(gen_random_bytes(6),'hex'),1,10))), status public.order_status not null default 'pending', subtotal numeric(14,2) not null check(subtotal>=0), shipping_fee numeric(14,2) not null default 0 check(shipping_fee>=0), total numeric(14,2) not null check(total>=0), currency text not null default 'SDG', address_snapshot jsonb not null, created_at timestamptz not null default now());
create table public.order_items(id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id) on delete cascade, product_id uuid references public.products(id), store_id uuid references public.stores(id), product_name text not null, unit_price numeric(14,2) not null, quantity integer not null check(quantity>0), line_total numeric(14,2) not null);
create table public.payments(id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id), method text not null check(method in ('cash_on_delivery','bank_transfer','bankak','mycashi','fawry','braaavo')), status public.payment_status not null default 'unpaid', amount numeric(14,2) not null check(amount>=0), reference text, proof_url text, verified_by uuid references auth.users(id), verified_at timestamptz, created_at timestamptz not null default now());
create table public.seller_plans(id uuid primary key default gen_random_uuid(), name text not null, price numeric(14,2) not null, currency text not null default 'SDG', duration_days integer not null check(duration_days>0), commission_percent numeric(5,2) not null default 0 check(commission_percent between 0 and 100), active boolean not null default true);
create table public.seller_subscriptions(id uuid primary key default gen_random_uuid(), store_id uuid not null references public.stores(id), plan_id uuid not null references public.seller_plans(id), starts_at timestamptz, ends_at timestamptz, status text not null default 'pending', payment_id uuid references public.payments(id));
create table public.favorites(user_id uuid not null references auth.users(id) on delete cascade, product_id uuid not null references public.products(id) on delete cascade, created_at timestamptz not null default now(), primary key(user_id,product_id));
create table public.audit_logs(id bigint generated always as identity primary key, actor_id uuid references auth.users(id), action text not null, entity text not null, entity_id text, metadata jsonb not null default '{}', created_at timestamptz not null default now());
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role='admin') $$;
create or replace function public.owns_store(target uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.stores where id=target and owner_id=auth.uid()) $$;
-- Enable RLS on every user-facing table.
alter table public.profiles enable row level security; alter table public.seller_applications enable row level security; alter table public.stores enable row level security; alter table public.categories enable row level security; alter table public.products enable row level security; alter table public.addresses enable row level security; alter table public.orders enable row level security; alter table public.order_items enable row level security; alter table public.payments enable row level security; alter table public.seller_plans enable row level security; alter table public.seller_subscriptions enable row level security; alter table public.favorites enable row level security; alter table public.audit_logs enable row level security;
create policy "profiles read own or admin" on public.profiles for select using(id=auth.uid() or public.is_admin());
create policy "profiles update own" on public.profiles for update using(id=auth.uid()) with check(id=auth.uid() and role='customer');
create policy "profile insert own" on public.profiles for insert with check(id=auth.uid());
create policy "applications own read" on public.seller_applications for select using(user_id=auth.uid() or public.is_admin());
create policy "applications own create" on public.seller_applications for insert with check(user_id=auth.uid());
create policy "applications admin update" on public.seller_applications for update using(public.is_admin()) with check(public.is_admin());
create policy "stores public approved" on public.stores for select using(status='approved' or owner_id=auth.uid() or public.is_admin());
create policy "stores owner create" on public.stores for insert with check(owner_id=auth.uid());
create policy "stores owner update" on public.stores for update using(owner_id=auth.uid() or public.is_admin()) with check(owner_id=auth.uid() or public.is_admin());
create policy "categories public read" on public.categories for select using(active or public.is_admin());
create policy "categories admin manage" on public.categories for all using(public.is_admin()) with check(public.is_admin());
create policy "products public active" on public.products for select using(active or public.owns_store(store_id) or public.is_admin());
create policy "products seller manage" on public.products for all using(public.owns_store(store_id) or public.is_admin()) with check(public.owns_store(store_id) or public.is_admin());
create policy "addresses own" on public.addresses for all using(user_id=auth.uid() or public.is_admin()) with check(user_id=auth.uid() or public.is_admin());
create policy "orders customer read" on public.orders for select using(user_id=auth.uid() or public.is_admin());
create policy "orders customer create" on public.orders for insert with check(user_id=auth.uid());
create policy "order items customer read" on public.order_items for select using(exists(select 1 from public.orders o where o.id=order_id and o.user_id=auth.uid()) or public.owns_store(store_id) or public.is_admin());
create policy "order items create via owner" on public.order_items for insert with check(exists(select 1 from public.orders o where o.id=order_id and o.user_id=auth.uid()));
create policy "payments own read" on public.payments for select using(exists(select 1 from public.orders o where o.id=order_id and o.user_id=auth.uid()) or public.is_admin());
create policy "payments own create" on public.payments for insert with check(exists(select 1 from public.orders o where o.id=order_id and o.user_id=auth.uid()));
create policy "payments admin update" on public.payments for update using(public.is_admin()) with check(public.is_admin());
create policy "plans public read" on public.seller_plans for select using(active or public.is_admin());
create policy "plans admin manage" on public.seller_plans for all using(public.is_admin()) with check(public.is_admin());
create policy "subscriptions own" on public.seller_subscriptions for select using(public.owns_store(store_id) or public.is_admin());
create policy "subscriptions admin manage" on public.seller_subscriptions for all using(public.is_admin()) with check(public.is_admin());
create policy "favorites own" on public.favorites for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "audit admin read" on public.audit_logs for select using(public.is_admin());
-- Create profile on signup; role is always customer regardless of client metadata.
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,full_name) values(new.id,coalesce(new.raw_user_meta_data->>'full_name','')); return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
